#!/usr/bin/env python3

# Some portions generated by Codex

from __future__ import annotations

import importlib.util
import json
import tempfile
import unittest
from pathlib import Path
from types import SimpleNamespace


REPOSITORY_ROOT = Path(__file__).resolve().parents[1]
SCRIPT = REPOSITORY_ROOT / "scripts" / "run-theme-plan-quality-campaign.py"


def load_campaign_module():
    spec = importlib.util.spec_from_file_location("theme_plan_quality_campaign", SCRIPT)
    if spec is None or spec.loader is None:
        raise AssertionError(f"unable to load {SCRIPT}")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def write_json(path: Path, value: object) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(value) + "\n", encoding="utf-8")


def succeeded(path: Path) -> None:
    write_json(path, {"formatVersion": 1, "outcome": "succeeded"})


class ThemePlanQualityCampaignTest(unittest.TestCase):

    def setUp(self) -> None:
        self.campaign = load_campaign_module()

    def test_summary_uses_complete_result_equal_alternative_medians(self) -> None:
        with tempfile.TemporaryDirectory() as directory:
            results = Path(directory)
            inventory = results / "inventory" / "social_media-q4.json"
            write_json(
                inventory,
                {
                    "formatVersion": 1,
                    "kind": "inventory",
                    "theme": "SOCIAL_MEDIA",
                    "queryIndex": 4,
                    "alternatives": [
                        {"index": 0, "stableId": "selected", "selectedByPolicy": True},
                        {"index": 1, "stableId": "faster", "selectedByPolicy": False},
                    ],
                },
            )
            succeeded(inventory.with_suffix(".status.json"))
            for index, stable_id, elapsed in (
                (0, "selected", [120, 100, 110]),
                (1, "faster", [100, 80, 90]),
            ):
                execution = results / "execution" / f"social_media-q4-alt{index}.json"
                write_json(
                    execution,
                    {
                        "formatVersion": 1,
                        "kind": "execution",
                        "theme": "SOCIAL_MEDIA",
                        "queryIndex": 4,
                        "alternativeIndex": index,
                        "stableId": stable_id,
                        "selectedByPolicy": index == 0,
                        "elapsedNanos": elapsed,
                        "fingerprintAlgorithm": "rdf4j-solution-bag-v1",
                        "rowCount": 7,
                        "bagFingerprint": "same-bag",
                    },
                )
                succeeded(execution.with_suffix(".status.json"))

            summary = self.campaign.summarize_campaign(
                results, (("SOCIAL_MEDIA", 4),)
            )

            self.assertEqual("complete", summary["status"])
            self.assertEqual(1, summary["completeCellCount"])
            self.assertEqual(2, summary["completedAlternativeCount"])
            self.assertAlmostEqual(110 / 90 - 1, summary["medianRegretFraction"])
            self.assertAlmostEqual(110 / 90 - 1, summary["p95RegretFraction"])
            self.assertEqual("complete", summary["cells"][0]["status"])
            self.assertEqual(110, summary["cells"][0]["selectedMedianNanos"])
            self.assertEqual(90, summary["cells"][0]["bestMedianNanos"])

    def test_summary_keeps_missing_and_mismatched_alternatives_explicit(self) -> None:
        with tempfile.TemporaryDirectory() as directory:
            results = Path(directory)
            inventory = results / "inventory" / "library-q10.json"
            write_json(
                inventory,
                {
                    "formatVersion": 1,
                    "kind": "inventory",
                    "theme": "LIBRARY",
                    "queryIndex": 10,
                    "alternatives": [
                        {"index": 0, "stableId": "selected", "selectedByPolicy": True},
                        {"index": 1, "stableId": "other", "selectedByPolicy": False},
                    ],
                },
            )
            succeeded(inventory.with_suffix(".status.json"))
            execution = results / "execution" / "library-q10-alt0.json"
            write_json(
                execution,
                {
                    "formatVersion": 1,
                    "kind": "execution",
                    "theme": "LIBRARY",
                    "queryIndex": 10,
                    "alternativeIndex": 0,
                    "stableId": "stale-selected-id",
                    "selectedByPolicy": True,
                    "elapsedNanos": [10, 11, 12],
                    "fingerprintAlgorithm": "rdf4j-solution-bag-v1",
                    "rowCount": 3,
                    "bagFingerprint": "bag",
                },
            )
            succeeded(execution.with_suffix(".status.json"))

            summary = self.campaign.summarize_campaign(
                results, (("LIBRARY", 10),)
            )

            self.assertEqual("incomplete", summary["status"])
            self.assertEqual(0, summary["completeCellCount"])
            self.assertIsNone(summary["medianRegretFraction"])
            self.assertEqual(
                ["alternative-0-stale", "alternative-1-missing"],
                summary["cells"][0]["issues"],
            )

    def test_resume_requires_success_and_exact_identity(self) -> None:
        with tempfile.TemporaryDirectory() as directory:
            root = Path(directory)
            result = root / "result.json"
            status = root / "result.status.json"
            write_json(
                result,
                {
                    "kind": "execution",
                    "theme": "TRAIN",
                    "queryIndex": 8,
                    "alternativeIndex": 3,
                    "stableId": "candidate-3",
                },
            )
            succeeded(status)

            expected = {
                "kind": "execution",
                "theme": "TRAIN",
                "queryIndex": 8,
                "alternativeIndex": 3,
                "stableId": "candidate-3",
            }
            self.assertTrue(self.campaign.completed_result(status, result, expected))
            self.assertFalse(
                self.campaign.completed_result(
                    status, result, expected | {"stableId": "new-candidate-3"}
                )
            )
            write_json(status, {"formatVersion": 1, "outcome": "timeout"})
            self.assertFalse(self.campaign.completed_result(status, result, expected))

    def test_resume_rejects_another_jar_or_measurement_protocol(self) -> None:
        with tempfile.TemporaryDirectory() as directory:
            root = Path(directory)
            jar = root / "candidate.jar"
            jar.write_bytes(b"candidate")
            old_jar = root / "old.jar"
            old_jar.write_bytes(b"old")
            args = SimpleNamespace(
                jar=jar,
                store_root=root / "store",
                dominated_samples=2,
                warmups=1,
                measurements=3,
                query_timeout_seconds=60,
                max_retained_bytes=256 * 1024 * 1024,
                frontier_heap_bytes=768 * 1024 * 1024,
            )
            result = root / "execution" / "train-q8-alt3.json"
            expected = {
                "kind": "execution",
                "theme": "TRAIN",
                "queryIndex": 8,
                "alternativeIndex": 3,
                "stableId": "candidate-3",
            }
            write_json(result, expected)
            command = self.campaign.audit_command(args, "TRAIN", 8, 3, result)
            status = result.with_suffix(".status.json")
            write_json(
                status,
                {"formatVersion": 1, "outcome": "succeeded", "command": command},
            )

            self.assertTrue(
                self.campaign.completed_result(
                    status,
                    result,
                    expected,
                    expected_command=command,
                    jar=jar,
                )
            )
            stale_jar_command = list(command)
            stale_jar_command[stale_jar_command.index("-cp") + 1] = str(old_jar)
            write_json(
                status,
                {
                    "formatVersion": 1,
                    "outcome": "succeeded",
                    "command": stale_jar_command,
                },
            )
            self.assertFalse(
                self.campaign.completed_result(
                    status,
                    result,
                    expected,
                    expected_command=command,
                    jar=jar,
                )
            )

            stale_settings_command = list(command)
            stale_settings_command[stale_settings_command.index("--measurements") + 1] = "2"
            write_json(
                status,
                {
                    "formatVersion": 1,
                    "outcome": "succeeded",
                    "command": stale_settings_command,
                },
            )
            self.assertFalse(
                self.campaign.completed_result(
                    status,
                    result,
                    expected,
                    expected_command=command,
                    jar=jar,
                )
            )

    def test_audit_command_carries_explicit_retained_byte_limit(self) -> None:
        with tempfile.TemporaryDirectory() as directory:
            root = Path(directory)
            jar = root / "candidate.jar"
            jar.write_bytes(b"candidate")
            args = SimpleNamespace(
                jar=jar,
                store_root=root / "store",
                dominated_samples=2,
                warmups=1,
                measurements=3,
                query_timeout_seconds=60,
                max_retained_bytes=256 * 1024 * 1024,
                frontier_heap_bytes=768 * 1024 * 1024,
            )

            command = self.campaign.audit_command(
                args, "SPARSE", 6, -1, root / "inventory.json"
            )

            option = command.index("--max-retained-bytes")
            self.assertEqual(str(256 * 1024 * 1024), command[option + 1])
            option = command.index("--frontier-heap-bytes")
            self.assertEqual(str(768 * 1024 * 1024), command[option + 1])

    def test_summary_marks_successful_status_from_another_jar_stale(self) -> None:
        with tempfile.TemporaryDirectory() as directory:
            root = Path(directory)
            jar = root / "candidate.jar"
            jar.write_bytes(b"candidate")
            old_jar = root / "old.jar"
            old_jar.write_bytes(b"old")
            args = SimpleNamespace(
                jar=jar,
                store_root=root / "store",
                dominated_samples=2,
                warmups=1,
                measurements=3,
                query_timeout_seconds=60,
                max_retained_bytes=256 * 1024 * 1024,
                frontier_heap_bytes=768 * 1024 * 1024,
            )
            inventory = root / "inventory" / "train-q8.json"
            write_json(
                inventory,
                {
                    "kind": "inventory",
                    "theme": "TRAIN",
                    "queryIndex": 8,
                    "alternatives": [
                        {"index": 0, "stableId": "selected", "selectedByPolicy": True}
                    ],
                },
            )
            command = self.campaign.audit_command(args, "TRAIN", 8, -1, inventory)
            command[command.index("-cp") + 1] = str(old_jar)
            write_json(
                inventory.with_suffix(".status.json"),
                {"formatVersion": 1, "outcome": "succeeded", "command": command},
            )

            summary = self.campaign.summarize_campaign(
                root, (("TRAIN", 8),), args
            )

            self.assertEqual("incomplete", summary["status"])
            self.assertEqual(["inventory-stale"], summary["cells"][0]["issues"])

    def test_summary_never_computes_regret_from_incomplete_search(self) -> None:
        with tempfile.TemporaryDirectory() as directory:
            results = Path(directory)
            inventory = results / "inventory" / "social_media-q10.json"
            write_json(
                inventory,
                {
                    "formatVersion": 2,
                    "kind": "inventory",
                    "theme": "SOCIAL_MEDIA",
                    "queryIndex": 10,
                    "completionStatus": "INCOMPLETE_RESOURCE_LIMIT",
                    "alternatives": [
                        {
                            "index": 0,
                            "stableId": "selected",
                            "selectedByPolicy": True,
                            "decisionTrace": self.exact_trace(),
                        }
                    ],
                },
            )
            succeeded(inventory.with_suffix(".status.json"))

            summary = self.campaign.summarize_campaign(
                results, (("SOCIAL_MEDIA", 10),)
            )

            self.assertEqual("incomplete", summary["status"])
            self.assertEqual(
                ["search-INCOMPLETE_RESOURCE_LIMIT"], summary["cells"][0]["issues"]
            )
            self.assertIsNone(summary["cells"][0]["regretFraction"])

    def test_schema_two_inventory_rejects_scalar_or_missing_frontier_state(self) -> None:
        scalar_trace = self.exact_trace()
        scalar_trace["alternatives"][0]["eventState"]["scalarFallback"] = True
        scalar_trace["alternatives"][0]["eventState"]["output"] = 0
        inventory = {
            "formatVersion": 2,
            "completionStatus": "EXACT_COMPLETE",
            "alternatives": [
                {
                    "index": 0,
                    "stableId": "selected",
                    "selectedByPolicy": True,
                    "decisionTrace": scalar_trace,
                }
            ],
        }

        with self.assertRaisesRegex(ValueError, "Frontier state continuity"):
            self.campaign.inventory_alternatives(inventory)

    @staticmethod
    def exact_trace() -> dict[str, object]:
        return {
            "schema": 2,
            "alternatives": [
                {
                    "event": 1,
                    "eventState": {
                        "output": 1,
                        "eventDigest": "event-digest",
                        "scalarFallback": False,
                    },
                }
            ],
        }


if __name__ == "__main__":
    unittest.main()
